def add(self, sku, qty=1):
    """加购。SKU 不存在会由 catalog 抛 KeyError；数量必须为正且不超过库存。"""
    if qty <= 0:
        raise ValueError("数量必须为正")
    item = catalog.get_item(sku)      # 校验 SKU 存在
    qty = int(qty)
    if qty > item["stock"]:
        raise ValueError(f"库存不足：{sku} 仅剩 {item['stock']} 件")
    self._lines.append((sku, qty))
    return self
